{
  "name": "emu-ingest",
  "version": "0.1.0",
  "description": "EMU notification ingest service - receives BNN alerts from Android phones, writes to Postgres",
  "type": "module",
  "main": "src/server.js",
  "scripts": {
    "dev": "node --watch src/server.js",
    "start": "node src/server.js",
    "test": "node --test test/",
    "lint": "echo 'add eslint later'",
    "typecheck": "echo 'add tsc later'"
  },
  "engines": {
    "node": ">=20.0.0"
  },
  "dependencies": {
    "fastify": "^4.28.1",
    "@fastify/cors": "^9.0.1",
    "pg": "^8.13.0",
    "zod": "^3.23.8",
    "pino": "^9.4.0",
    "pino-pretty": "^11.2.2",
    "dotenv": "^16.4.5",
    "node-cron": "^3.0.3"
  },
  "devDependencies": {}
}

// src/server.js
// EMU notification ingest service.
// Receives BNN alert POSTs from Android capture phones (notification-database or nfa-alerts-v2).
// Validates with Zod, normalizes, geocodes, dedups, persists to Postgres.
// Listens on Tailscale interface; bearer-token authenticated.

import Fastify from 'fastify';
import cors from '@fastify/cors';
import pg from 'pg';
import { z } from 'zod';
import 'dotenv/config';

const { Pool } = pg;

const PORT = parseInt(process.env.PORT || '8787', 10);
const HOST = process.env.HOST || '0.0.0.0';          // bind all interfaces (Tailscale magic will reach it)
const INGEST_TOKEN = process.env.EMU_INGEST_TOKEN;     // shared secret with the Android app
const DATABASE_URL = process.env.DATABASE_URL;         // postgres://user:pass@host:port/db

if (!INGEST_TOKEN) {
  console.error('FATAL: EMU_INGEST_TOKEN env var not set');
  process.exit(1);
}
if (!DATABASE_URL) {
  console.error('FATAL: DATABASE_URL env var not set');
  process.exit(1);
}

const pool = new Pool({ connectionString: DATABASE_URL, max: 10 });

// ============================================================
// Validation schema for incoming notifications
// Accepts the BNN notification payload from the Android capture app.
// ============================================================
const NotificationSchema = z.object({
  source: z.literal('bnn').default('bnn'),
  // The raw notification text from the Android system
  raw: z.object({
    packageName: z.string(),
    title: z.string().optional(),
    text: z.string().optional(),
    bigText: z.string().optional(),
    subText: z.string().optional(),
    summaryText: z.string().optional(),
    tickerText: z.string().optional(),
    postedAt: z.number().int(),     // ms since epoch
  }),
  // Optional pre-parsed fields if the Android app did LLM parsing
  parsed: z.object({
    external_id: z.string().optional(),
    type: z.enum(['fire', 'medical', 'other']).optional(),
    severity: z.string().optional(),
    address_raw: z.string().optional(),
    fire_dept_fdid: z.string().optional(),
    state: z.string().length(2).optional(),
    county: z.string().optional(),
  }).optional(),
  // Device identity (so we can attribute alerts to a specific capture device)
  device: z.object({
    id: z.string(),
    name: z.string().optional(),
    tailscale_ip: z.string().optional(),
  }).optional(),
});

const app = Fastify({
  logger: {
    transport: {
      target: 'pino-pretty',
      options: { translateTime: 'HH:MM:ss', ignore: 'pid,hostname' }
    }
  }
});

await app.register(cors, { origin: false });

// ============================================================
// Auth: bearer token check
// ============================================================
app.addHook('onRequest', async (req, reply) => {
  if (req.url === '/api/health') return; // public health
  const auth = req.headers.authorization;
  if (auth !== `Bearer ${INGEST_TOKEN}`) {
    req.log.warn({ url: req.url, ip: req.ip }, 'auth_failed');
    reply.code(401).send({ ok: false, error: 'unauthorized' });
  }
});

// ============================================================
// Health check
// ============================================================
app.get('/api/health', async () => {
  const dbStart = Date.now();
  let dbOk = false;
  try {
    const r = await pool.query('SELECT 1 AS ok');
    dbOk = r.rows[0].ok === 1;
  } catch (e) {
    dbOk = false;
  }
  return {
    ok: dbOk,
    service: 'emu-ingest',
    version: '0.1.0',
    db: dbOk ? 'up' : 'down',
    db_latency_ms: Date.now() - dbStart,
    ts: new Date().toISOString(),
  };
});

// ============================================================
// Ingest endpoint
// Accepts a notification payload, normalizes, persists, returns ingest_id.
// ============================================================
app.post('/api/ingest', async (req, reply) => {
  const parse = NotificationSchema.safeParse(req.body);
  if (!parse.success) {
    req.log.warn({ errors: parse.error.flatten() }, 'validation_failed');
    return reply.code(400).send({ ok: false, error: 'validation_failed', details: parse.error.flatten() });
  }
  const notif = parse.data;

  // Build a normalized record (best-effort; LLM parsing happens in a later stage)
  const postedAt = new Date(notif.raw.postedAt);
  const parsed = notif.parsed || {};
  const addressRaw = parsed.address_raw || notif.raw.bigText || notif.raw.text || notif.raw.title || '';
  const externalId = parsed.external_id || null;
  const fireDeptFdid = parsed.fire_dept_fdid || null;

  // Dedup key: hash of (external_id, postedAt, fireDeptFdid)
  const dedupKey = await sha256Hex([externalId || '', postedAt.toISOString(), fireDeptFdid || ''].join('|'));

  // Try to find an existing alert with the same dedup_key in the last 5 minutes
  const existing = await pool.query(
    `SELECT id FROM alerts
     WHERE external_id = $1
       AND reported_at > NOW() - INTERVAL '24 hours'
     LIMIT 1`,
    [externalId]
  );

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Always log the ingest first
    const logRes = await client.query(
      `INSERT INTO ingest_log (source, raw_payload, normalized, dedup_key, status)
       VALUES ($1, $2, $3, $4, 'received')
       RETURNING id`,
      [notif.source, req.body, notif, dedupKey]
    );
    const ingestLogId = logRes.rows[0].id;

    if (existing.rows.length > 0) {
      // It's an update to an existing alert
      const alertId = existing.rows[0].id;
      const seqRes = await client.query(
        `SELECT COALESCE(MAX(sequence), 0) + 1 AS next_seq FROM alert_updates WHERE alert_id = $1`,
        [alertId]
      );
      const sequence = seqRes.rows[0].next_seq;
      await client.query(
        `INSERT INTO alert_updates (alert_id, sequence, payload, parsed)
         VALUES ($1, $2, $3, $4)`,
        [alertId, sequence, req.body, notif]
      );
      await client.query(
        `UPDATE ingest_log SET status = 'deduped', alert_id = $1 WHERE id = $2`,
        [alertId, ingestLogId]
      );
      await client.query('COMMIT');
      req.log.info({ alertId, sequence, ingestLogId }, 'alert_update');
      return { ok: true, mode: 'update', alert_id: alertId, sequence, ingest_log_id: ingestLogId };
    }

    // Try to match the fire department by FDID
    let fireDeptId = null;
    if (fireDeptFdid) {
      const fdRes = await client.query(
        `SELECT id FROM fire_departments WHERE fdid = $1 LIMIT 1`,
        [fireDeptFdid]
      );
      if (fdRes.rows.length > 0) fireDeptId = fdRes.rows[0].id;
    }

    // Insert the new alert (raw, pre-geocode)
    const alertRes = await client.query(
      `INSERT INTO alerts
        (external_id, fire_dept_id, fire_dept_fdid, type, severity, address_raw,
         state, status, source, raw_payload, reported_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, 'active', $8, $9, $10)
       RETURNING id, reported_at`,
      [
        externalId,
        fireDeptId,
        fireDeptFdid,
        parsed.type || 'other',
        parsed.severity || null,
        addressRaw,
        parsed.state || null,
        notif.source,
        req.body,
        postedAt,
      ]
    );
    const alertId = alertRes.rows[0].id;

    // Insert the initial alert_update
    await client.query(
      `INSERT INTO alert_updates (alert_id, sequence, payload, parsed)
       VALUES ($1, 0, $2, $3)`,
      [alertId, req.body, notif]
    );

    await client.query(
      `UPDATE ingest_log SET status = 'parsed', alert_id = $1 WHERE id = $2`,
      [alertId, ingestLogId]
    );
    await client.query('COMMIT');
    req.log.info({ alertId, externalId, fireDeptFdid, ingestLogId }, 'alert_created');

    // Fire-and-forget: enqueue a geocoding job (simple, we just write a row to indicate "needs geocode")
    // The actual geocoding happens out-of-band (later service)

    return { ok: true, mode: 'create', alert_id: alertId, ingest_log_id: ingestLogId };
  } catch (e) {
    await client.query('ROLLBACK');
    req.log.error({ err: e.message, stack: e.stack }, 'ingest_failed');
    return reply.code(500).send({ ok: false, error: 'ingest_failed', message: e.message });
  } finally {
    client.release();
  }
});

// ============================================================
// Stats endpoint (for Tony's home dashboard)
// ============================================================
app.get('/api/stats', async () => {
  const [alerts24h, alertsTotal, last24ByFd, gaps] = await Promise.all([
    pool.query(`SELECT COUNT(*)::int AS n FROM alerts WHERE reported_at > NOW() - INTERVAL '24 hours'`),
    pool.query(`SELECT COUNT(*)::int AS n FROM alerts`),
    pool.query(`
      SELECT fd.department_name, COUNT(a.id)::int AS n
      FROM alerts a
      JOIN fire_departments fd ON fd.id = a.fire_dept_id
      WHERE a.reported_at > NOW() - INTERVAL '24 hours'
      GROUP BY fd.department_name
      ORDER BY n DESC
      LIMIT 10
    `),
    pool.query(`
      SELECT COUNT(*)::int AS n FROM v_coverage_gaps_24h WHERE alerts_24h = 0
    `),
  ]);
  return {
    ok: true,
    alerts_24h: alerts24h.rows[0].n,
    alerts_total: alertsTotal.rows[0].n,
    top_departments_24h: last24ByFd.rows,
    coverage_gaps_24h: gaps.rows[0].n,
    ts: new Date().toISOString(),
  };
});

// ============================================================
// Helpers
// ============================================================
async function sha256Hex(input) {
  const enc = new TextEncoder().encode(input);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// ============================================================
// Boot
// ============================================================
try {
  await app.listen({ port: PORT, host: HOST });
  app.log.info(`EMU ingest service listening on http://${HOST}:${PORT}`);
} catch (e) {
  app.log.error(e);
  process.exit(1);
}

// Graceful shutdown
for (const sig of ['SIGINT', 'SIGTERM']) {
  process.on(sig, async () => {
    app.log.info(`received ${sig}, shutting down`);
    await app.close();
    await pool.end();
    process.exit(0);
  });
}

